/**
 * Legacy → new page-path redirects (301), applied prefix-first so sub-paths and
 * query strings carry over. Covers the showroom→shopping rebrand and the
 * admin-route normalization (root pages moved under /admin/*).
 *
 * Handled here rather than via Astro's `redirects` config because the Cloudflare
 * adapter emits a malformed self-referential `_redirects` splat rule for dynamic
 * destinations (wrangler rejects it: "infinite loop detected").
 *
 * Prefix matching uses `=== from || startsWith(from + "/")`, so `/admin/showroom`
 * never swallows the distinct legacy `/admin/showrooms/...` route, and `/measure`
 * never swallows `/measurements`.
 */
const LEGACY_REDIRECTS: ReadonlyArray<readonly [string, string]> = [
  ["/admin/showroom", "/admin/shopping"],
  ["/admin/shopping-journal", "/admin/shopping/journal"],
  ["/rooms/closets", "/admin/shopping/closets"],
  ["/uploads", "/admin/prepare/uploads"],
  ["/review", "/admin/prepare/review"],
  ["/photo-edits", "/admin/photo-edits"],
  ["/builder", "/admin/builder"],
  ["/gallery", "/admin/gallery"],
  ["/bid-portfolios", "/admin/bids"],
  ["/measurements", "/admin/measurements"],
  // Admin namespace reorg (budget / pmo / planning). Old flat + root paths land
  // directly on the new namespaced URLs (single hop — no redirect chains).
  ["/budget-tracker", "/admin/budget/tracker"],
  ["/budget-dashboard", "/admin/budget/dashboard"],
  ["/budget-reconciliation", "/admin/budget/reconciliation"],
  ["/planning", "/admin/pmo/operations"],
  ["/measure", "/admin/planning/measure"],
  ["/admin/budget-tracker", "/admin/budget/tracker"],
  ["/admin/budget-dashboard", "/admin/budget/dashboard"],
  ["/admin/truth-table", "/admin/budget/truth-table"],
  ["/admin/contractor-schedule", "/admin/pmo/schedule/contractor"],
  ["/admin/measure", "/admin/planning/measure"],
  ["/admin/research", "/admin/planning/research"],
  // Admin namespace reorg slice 2 (designs / prepare / bids / config) + public
  // /photos·/log moves. Old flat/root paths land directly on the new URLs.
  ["/admin/uploads", "/admin/prepare/uploads"],
  ["/admin/review", "/admin/prepare/review"],
  ["/admin/blank-canvas", "/admin/prepare/blank-canvas"],
  ["/admin/bid-portfolios", "/admin/bids"],
  ["/admin/planning/decision-room", "/admin/designs/decision-room"],
  ["/admin/planning/moodboards", "/admin/designs/moodboards"],
  ["/admin/brands/types", "/admin/config/brands/types"],
  // Config moved under the admin auth gate — the public `/config/*` prefix should
  // never have served config. 301 old links (incl. /config/photo/*) to /admin/config.
  ["/config", "/admin/config"],
  // #118 shipped device landing prefs at /admin/config/preferences; it now lives
  // at /admin/config/device (D1-backed cards). Redirect the old path.
  ["/admin/config/preferences", "/admin/config/device"],
  // Brands live under the shopping suite (SITEMAP target). Registered AFTER the
  // /admin/brands/types entry above so the prefix loop resolves types first.
  ["/admin/brands", "/admin/shopping/brands"],
  // The health page now maps the whole backend (tables, bindings, failure modes)
  // and so moved behind the /admin gate, onto the /admin/system/* IA next to the
  // audit trail and logs. `GET /api/health` stays public for external uptime
  // monitors — only the human page moved.
  ["/health", "/admin/system/health"],
  ["/admin/health", "/admin/system/health"],
  ["/listing-photos", "/photos/listing"],
  ["/inspiration-photos", "/photos/inspiration"],
  ["/daily-log", "/log/daily"],
  ["/weekly-log", "/log/weekly"],
  // Phase 2 Documents system: the old static "Renovation Guide Center" audience
  // routes are deleted (SITEMAP.md "Deleted routes"); land them on the new /docs.
  // Safe alongside the dynamic /docs/[id] viewer — document ids are UUIDs, never
  // these audience slugs.
  ["/docs/homeowners", "/docs"],
  ["/docs/contractors", "/docs"],
  ["/docs/platform", "/docs"],
  ["/docs/shared", "/docs"],
];

const legacyHandler: ExportedHandler<Env> = {
  async fetch(request, env, ctx) {
    // MCP connector OAuth consent screen (0015). workers-oauth-provider
    // auto-serves /oauth/token, /oauth/register and the .well-known metadata,
    // but delegates the authorize endpoint here (env.OAUTH_PROVIDER is injected
    // by the provider). Handle it before agent routing / auth gates.
    const authorizeResponse = await handleOAuthAuthorize(request, env);
    if (authorizeResponse) return authorizeResponse;

    // Showroom Scout spends real Gemini and Google Maps quota on every run, so
    // its agent surface (HTTP + WebSocket) is gated before `routeAgentRequest`,
    // which otherwise runs ahead of every auth check in this Worker.
    //
    // Scoped deliberately to this one agent rather than all of them: the other
    // agent namespaces predate this gate and changing their auth posture is a
    // separate decision. That means the remaining `/agents/*` namespaces are
    // still open — see the note in the Showroom Scout README.
    const agentUrl = new URL(request.url);
    if (agentUrl.pathname.startsWith("/agents/showroom-scout")) {
      if (!(await isRequestAuthenticated(request, env))) {
        return new Response(JSON.stringify({ error: "Unauthorized" }), {
          status: 401,
          headers: { "content-type": "application/json" },
        });
      }
    }

    const agentResponse = await routeAgentRequest(request, env);
    if (agentResponse) return agentResponse;

    const url = new URL(request.url);

    // Legacy-path 301s (rebrand + admin-route normalization). Runs before auth so
    // old bookmarks land on the new URL (and then hit the /admin auth gate there).
    for (const [from, to] of LEGACY_REDIRECTS) {
      if (url.pathname === from || url.pathname.startsWith(`${from}/`)) {
        const rest = url.pathname.slice(from.length);
        return Response.redirect(`${url.origin}${to}${rest}${url.search}`, 301);
      }
    }

    // Device-scoped landing preference: an authed device that has chosen a
    // default landing page (from /admin/config/device) is redirected there when
    // it hits the app root exactly. The choice lives in D1 keyed by the device's
    // cookie id, so each device routes independently (Tesla → drives, phone →
    // showrooms). Only fires for authed devices; unauthed root hits fall through
    // to the normal home/login. Path is validated to block open-redirects.
    if (url.pathname === "/") {
      const deviceId = getDeviceIdFromRequest(request);
      // Auth is always required — a device that was an admin in the past still
      // must present a VALID admin cookie. An expired/absent cookie falls through
      // to the normal home/login and never gets an auto-redirect.
      if (await isRequestAuthenticated(request, env)) {
        // Active-drive override: while ONE drive list is active, admin devices
        // auto-land on it (temporary — reverts to the device's normal landing
        // once no drive is active). Takes precedence over the device pref.
        const drivePath = await getActiveDriveLandingPath(env);
        if (drivePath && isSafeInternalPath(drivePath)) {
          return Response.redirect(`${url.origin}${drivePath}`, 302);
        }
        // Otherwise fall back to the device's chosen landing page.
        if (deviceId) {
          const landing = await getDeviceLandingPath(env, deviceId);
          if (landing && landing !== "/" && isSafeInternalPath(landing)) {
            return Response.redirect(`${url.origin}${landing}`, 302);
          }
        }
      }
    }

    const protectedPaths = [
      "/admin",
      "/uploads",
      "/photo-edits",
      "/review",
      "/budget-tracker",
      "/budget-dashboard",
    ];

    const isProtectedPath = protectedPaths.some(
      (path) => url.pathname === path || url.pathname.startsWith(`${path}/`),
    );

    // Vendor portal host (remodel.hacolby.app, or ?_portal=1 on a non-prod host):
    // it serves ONLY the guest portal. Root lands on the floor plan; every
    // homeowner-protected surface (the full `protectedPaths` denylist) plus the
    // login page are redirected away — a vendor should never see them. Reusing
    // `protectedPaths` means a newly-added protected route is covered automatically.
    // API requests fall through (guest + public endpoints work; every homeowner
    // endpoint stays gated by its own auth, independent of host).
    if (isGuestPortalRequest(request) && !url.pathname.startsWith("/api/")) {
      if (url.pathname === "/") {
        return Response.redirect(`${url.origin}/floor-plan`, 302);
      }
      if (isProtectedPath || url.pathname === "/access") {
        return Response.redirect(`${url.origin}/floor-plan`, 302);
      }
    }

    if (
      url.pathname.startsWith("/api/realtime/estimates") ||
      url.pathname.startsWith("/api/realtime/plans")
    ) {
      // Both surfaces fan out through the same EstimateCollabHub DO, keyed by the
      // `room` param. Plan/task progress uses room `plan:<planSlug>` so an open
      // preview-changelog viewer gets a live poke when a task's status changes.
      const room = url.searchParams.get("room")?.trim() || "global";
      const stub = env.ESTIMATE_COLLAB.getByName(room);
      return stub.fetch(request);
    }

    // Real-time floor-plan sessions: /api/room/:roomName/ws (WebSocket upgrade +
    // /health). The Worker is a stateless gateway — it routes by room name to the
    // matching FloorplanSessionDO instance and offloads the socket to the DO.
    const floorplanRoom = url.pathname.match(/^\/api\/room\/([^/]+)\/(ws|health)$/);
    if (floorplanRoom) {
      const roomName = decodeURIComponent(floorplanRoom[1]);
      const stub = env.FLOORPLAN_SESSION.getByName(roomName);
      return stub.fetch(request);
    }

    // Discovery-finder realtime (0032 D2): /api/showrooms/discovery/ws|health?slug=<slug>.
    // One DiscoveryHub DO per search slug (room "search:<slug>"); the finder engine
    // publishes status/revision/results events an open finder page streams live.
    if (
      url.pathname === "/api/showrooms/discovery/ws" ||
      url.pathname === "/api/showrooms/discovery/health"
    ) {
      const slug = url.searchParams.get("slug")?.trim() || "global";
      const stub = env.DISCOVERY_HUB.getByName(`search:${slug}`);
      return stub.fetch(request);
    }

    // Handle API routes with Hono
    if (
      url.pathname.startsWith("/api/") ||
      url.pathname === "/api-docs" ||
      url.pathname === "/openapi.json" ||
      url.pathname === "/swagger" ||
      url.pathname === "/scalar" ||
      url.pathname === "/context"
    ) {
      return honoApp.fetch(request, env, ctx);
    }

    if (isProtectedPath) {
      const authenticated = await isRequestAuthenticated(request, env);
      if (!authenticated) {
        const redirect = new URL("/access", url.origin);
        redirect.searchParams.set("next", `${url.pathname}${url.search}`);
        return Response.redirect(redirect.toString(), 302);
      }
    }

    // Let Astro handle everything else (SSR and static assets via env.ASSETS)
    const astroResponse = await astroHandler.fetch!(request, env, ctx);

    // Studio artifact runtime (/studio-runtime) renders inside a
    // `sandbox="allow-scripts"` iframe, which gives the frame an OPAQUE origin.
    // Its Astro island hydrates by fetching `/_astro/*` module scripts, and a
    // module fetch from an opaque origin is cross-origin — so without CORS
    // headers the browser blocks it and the island never mounts (blank frame).
    // Build assets are public app code, so it's safe to allow any origin.
    if (url.pathname.startsWith("/_astro/")) {
      const headers = new Headers(astroResponse.headers);
      headers.set("Access-Control-Allow-Origin", "*");
      headers.set("Cross-Origin-Resource-Policy", "cross-origin");
      // Cached assets return a null-body status (304 on conditional GETs, 204);
      // passing a body to `new Response` for those throws a TypeError in Workers.
      const body = [204, 304].includes(astroResponse.status) ? null : astroResponse.body;
      return new Response(body, {
        status: astroResponse.status,
        statusText: astroResponse.statusText,
        headers,
      });
    }

    return astroResponse;
  },
  async email(message, env, ctx) {
    // Inbound email → routing layer. The router applies auto-reply/loop
    // protection, resolves the recipient address to a route (invoices /
    // contracts / catch-all), rejects unknown recipients, and dispatches to
    // the background processing pipeline. See src/backend/services/email/.
    const { handleInboundEmail } = await import("./backend/services/email");
    await handleInboundEmail(message, env, ctx);
  },
  async scheduled(event, env, ctx) {
    // Gate by cron expression so each registered trigger fires its own job.
    // The existing 14:00 UTC trigger runs the permit sync; the new master-tick
    // "* * * * *" reads `system_cron_schedules` and fires any due workflows.
    // Weekly provider price refresh. Its own trigger rather than a rider on the
    // daily job: it hits four external endpoints and must not share a failure
    // budget with the permit sync.
    if (event.cron === "0 9 * * 1") {
      ctx.waitUntil(refreshPricingCatalog(env).then(() => undefined));
      return;
    }
    if (event.cron === "0 14 * * *") {
      ctx.waitUntil(runPermitSync(env));
      // Prune the agent run ledger. Daily, not per-minute: a sweep that finds
      // nothing 1,439 times a day is pure waste, and an append-only ledger
      // written by every instrumented surface is exactly how a cost-monitoring
      // feature would otherwise become its own D1 row-read cost story.
      ctx.waitUntil(pruneAgentRuns(env));
      // Close out runs whose isolate died mid-flight. Must run BEFORE nothing —
      // it is what stops a crashed run from masquerading as a live Durable
      // Object in the runaway watcher for the rest of time.
      ctx.waitUntil(sweepAbandonedRuns(env).then(() => undefined));
      return;
    }
    if (event.cron === "* * * * *") {
      ctx.waitUntil(dispatchDueWorkflows(env));
      // Self-heal image uploads stranded by transient Workers AI capacity
      // errors (or whose workflow never started) without manual reprocessing.
      ctx.waitUntil(autoHealImageUploads(env));
      ctx.waitUntil(monitorShowroomSourcingCoverage(env));
      // Enforce the daytime window: a drive can only be active 07:00–20:00
      // Pacific, so deactivate one that has run past the close. Cheap (one
      // indexed read; a write only on the boundary tick).
      ctx.waitUntil(
        enforceStreamWindow(env)
          .then((r) => {
            if (r.deactivated)
              console.log(`[scheduled] drive '${r.slug}' deactivated: window closed`);
          })
          .catch((err) => console.error("[scheduled] stream window enforce failed:", err)),
      );
      // Vehicle polling — the FALLBACK ingest path. Self-gates: no active drive,
      // the streaming DO is carrying ingest, or a poll within the configured
      // cadence, and it's one indexed D1 read.
      ctx.waitUntil(
        pollVehicleForActiveDrive(env)
          .then((r) => {
            if (r.polled && r.latitude != null) {
              console.log(
                `[scheduled] tesla poll: shift=${r.shiftState} matched=${r.matchedStop?.name ?? "none"} ` +
                  `home=${r.homeArrival?.reason}`,
              );
            }
          })
          .catch((err) => console.error("[scheduled] tesla poll failed:", err)),
      );
      // One-shot re-enrichment of showroom website/hours/address from Google
      // Places (0108/0109 dropped the legacy columns before backfill). Processes
      // a small batch per tick and no-ops once every place_id store is done.
      ctx.waitUntil(
        backfillShowroomPlacesData(env)
          .then((r) => {
            if (r.processed > 0) {
              console.log(
                `[scheduled] showroom places backfill: processed=${r.processed} remaining=${r.remaining}`,
              );
            }
          })
          .catch((err) => console.error("[scheduled] showroom places backfill failed:", err)),
      );
      return;
    }
    if (event.cron === "15 */4 * * *") {
      // Gmail comms hub (0013 P3-07): bounded ingestion every 4 hours — see
      // wrangler.jsonc for why this is a dedicated trigger rather than
      // piggybacking the per-minute master tick.
      ctx.waitUntil(
        ingestCompanyEmails(env)
          .then((result) =>
            console.log(
              `[scheduled] gmail ingestion: companies=${result.companies} threads=${result.threads} messages=${result.messages}`,
            ),
          )
          .catch((err) => console.error("[scheduled] gmail ingestion failed:", err)),
      );
      // Safety-net: pull anything the user manually dropped into the
      // `core-remodel/inbox` Gmail label, then unlabel it. See inbox-label.ts.
      ctx.waitUntil(
        ingestInboxLabel(env)
          .then((r) => {
            if (r.found > 0) {
              console.log(
                `[scheduled] gmail inbox-label safety-net: found=${r.found} ingested=${r.ingested} skipped=${r.skipped}`,
              );
            }
          })
          .catch((err) => console.error("[scheduled] gmail inbox-label ingestion failed:", err)),
      );
      // 0039 ingest gate: pull vendor mail from the personal inbox whose
      // sender/recipient domain matches a known showroom or contractor company,
      // and bridge each into the shared extraction pipeline. Domain-filtered at
      // the Gmail search, so non-matching mail is never fetched (zero AI/OCR).
      ctx.waitUntil(
        runIngestGate(env)
          .then((r) => {
            if (r.newMessages > 0 || r.failed > 0) {
              console.log(
                `[scheduled] gmail ingest-gate: domains=${r.domainsSearched} candidates=${r.candidates} ` +
                  `new=${r.newMessages} processed=${r.processed} failed=${r.failed}`,
              );
            }
          })
          .catch((err) => console.error("[scheduled] gmail ingest-gate failed:", err)),
      );
      return;
    }
    if (event.cron === "30 13 * * 1") {
      // Weekly showroom sale/clearance sweep. First runs plain-fetch discovery to
      // register any new clearance/sale/outlet links across the whole directory
      // (sitemap.xml, or the homepage when a site has none), then hands the
      // WEBSITE_CLEARANCE links to the Jules DO (primary; Workers-AI fallback when
      // no JULES_API_KEY). A snapshot is only written when a page changed vs the
      // last scrape. NOTE: Cloudflare cron day-of-week is 1=Sunday, so this fires
      // SUNDAY 13:30 UTC, not Monday — matching the observed run history.
      ctx.waitUntil(
        startClearanceSweep(env)
          .then((r) =>
            console.log(
              `[scheduled] clearance sweep kicked off: mode=${r.mode} links=${r.links} ` +
                `job=${r.jobId ?? "n/a"} discovery=${r.discovery ? `+${r.discovery.newLinks} links/${r.discovery.storesScanned} stores` : "skipped"}`,
            ),
          )
          .catch((err) => console.error("[scheduled] clearance sweep failed:", err)),
      );
      return;
    }
    if (event.cron === "0 11 * * *") {
      ctx.waitUntil(
        (async () => {
          // Reuses the shared agent-run ledger rather than a bespoke scan-run
          // table, so the nightly scan shows up at /admin/system/agents for free.
          const run = await startRun(env, {
            agent: "drive-ingest",
            operation: "daily-scan",
            triggeredBy: "cron",
          });
          try {
            const roots = await listActiveRootsForCron(env);
            const summaries: IngestSummary[] = [];
            let failures = 0;
            for (const root of roots) {
              // One root's failure must not stop the rest — mirrors the same
              // guard in ingestAllActiveRoots. run.step already recorded the
              // error against this root's own step; catch here so the loop
              // keeps going instead of aborting the whole nightly run.
              try {
                summaries.push(
                  await run.step(`root:${root.label}`, () => ingestDriveFolder(env, root.id)),
                );
              } catch (err) {
                // A root whose lease is already held (a manual scan is running)
                // is SKIPPED, not failed — run.step has already recorded the
                // message against this root's own ledger step.
                if (!(err instanceof ScanInProgressError)) failures++;
                const summary = emptySummary(root.id, root.label);
                summary.errors.push(err instanceof Error ? err.message : String(err));
                summaries.push(summary);
              }
            }
            if (roots.length > 0 && failures === roots.length) {
              await run.fail(new Error(`all ${roots.length} drive root(s) failed to ingest`));
            } else {
              await run.succeed({ summaries });
            }
          } catch (err) {
            await run.fail(err);
          }
        })(),
      );
      return;
    }
    // Unknown trigger — log and ignore.
    console.warn(`scheduled: unhandled cron "${event.cron}"`);
  },
};

/**
 * MCP connector OAuth wrapper (0015).
 *
 * OAuthProvider owns the OAuth endpoints + the `.well-known` metadata, and
 * routes the MCP transport paths (`/mcp`, `/mcp/sse`) to the McpAgent DO with
 * the authenticated grant `props` attached. Everything else falls through to
 * `legacyHandler` (Astro SSR + Hono `/api/*` + Cloudflare Agents), which also
 * renders the `/oauth/authorize` consent screen.
 *
 * NOTE: OAuthProvider only implements `fetch`. The default export below
 * therefore delegates `fetch` to the provider but wires `scheduled` and
 * `email` straight to `legacyHandler` so the cron jobs (permit sync, workflow
 * dispatch, auto-heal, showroom monitor, Gmail ingest) and inbound email
 * routing keep working.
 */
/** Every MCP OAuth lifetime (access, refresh, client registration). */
const ONE_YEAR_SECONDS = 365 * 24 * 60 * 60;

/**
 * Pin `props.codeMode` for this request before the McpAgent sees it, so the DO
 * knows which surface to build (see RemodelMcpAgent.init). OAuthProvider has
 * already populated `ctx.props` from the grant by the time an apiHandler runs,
 * so this merges rather than replaces.
 */
function withCodeMode(handler: FetchHandler, codeMode: boolean): FetchHandler {
  return {
    fetch(request, env, ctx) {
      const withProps = ctx as ExecutionContext & { props?: Record<string, unknown> };
      withProps.props = { ...(withProps.props ?? {}), codeMode };
      return handler.fetch(request, env, ctx);
    },
  };
}

/**
 * Every MCP transport, shared by BOTH auth paths below — the OAuthProvider
 * (claude.ai and any other OAuth client) and the direct API-key path. Declared
 * once so the two can never drift apart.
 *
 * TWO SURFACES: `/mcp` serves Code Mode (a single `code` tool carrying typed
 * declarations for the whole registry — 170+ tool schemas would otherwise cost
 * a fortune in context on every connection), `/mcp/direct` serves the classic
 * one-tool-per-tool shape as the fallback while Code Mode is experimental.
 * Both are built from the same fully-populated server.
 *
 * ORDER IS LOAD-BEARING. OAuthProvider matches an apiHandler with
 * `pathname.startsWith(route)` and takes the FIRST hit in insertion order, so
 * a bare `/mcp` listed first would swallow `/mcp/sse` and `/mcp/direct`
 * outright. Longest paths first, always.
 *
 * Each is wrapped with the SSE keepalive (0032 K1) so a `: ping` frame every
 * 15s holds the long-lived voice-session socket open. Non-SSE (normal
 * text-chat JSON) responses pass through untouched.
 */
const MCP_HANDLERS: Record<string, FetchHandler> = {
  "/mcp/direct/sse": withCodeMode(
    withSseHeartbeat(RemodelMcpAgent.serveSSE("/mcp/direct/sse", { binding: "REMODEL_MCP" })),
    false,
  ),
  "/mcp/direct": withCodeMode(
    withSseHeartbeat(RemodelMcpAgent.serve("/mcp/direct", { binding: "REMODEL_MCP" })),
    false,
  ),
  "/mcp/sse": withCodeMode(
    withSseHeartbeat(RemodelMcpAgent.serveSSE("/mcp/sse", { binding: "REMODEL_MCP" })),
    true,
  ),
  "/mcp": withCodeMode(
    withSseHeartbeat(RemodelMcpAgent.serve("/mcp", { binding: "REMODEL_MCP" })),
    true,
  ),
};

/**
 * Direct (non-OAuth) access to the MCP transports for callers that hold the
 * shared operator key: `Authorization: Bearer <WORKER_API_KEY>`, the equivalent
 * `x-worker-api-key` header, or an already-authenticated browser session via
 * the `remodel_access` cookie — exactly the identities `isRequestAuthenticated`
 * already trusts everywhere else in the app.
 *
 * WHY: OAuthProvider owns the whole `/mcp` prefix and rejects anything that is
 * not one of its own minted access tokens, so a plain bearer key got a flat 401
 * and scripts/CLIs had no way onto the full tool surface — only the 21-tool
 * legacy `/api/mcp` shim. Checking here, ahead of the provider, adds the key
 * path without weakening OAuth: an OAuth bearer is not the worker key, so those
 * requests fail this check and fall through to the provider unchanged.
 *
 * Returns `null` when this request is not a key-authenticated MCP call, which
 * is the caller's signal to hand it to OAuthProvider.
 */
async function handleApiKeyMcpRequest(
  request: Request,
  env: Env,
  ctx: ExecutionContext,
): Promise<Response | null> {
  const handler = MCP_HANDLERS[new URL(request.url).pathname];
  if (!handler) return null;
  if (!(await isRequestAuthenticated(request, env))) return null;
  // McpAgent reads the caller identity off ctx.props (normally populated by
  // OAuthProvider from the grant). Stamp the key principal so tool handlers and
  // the mcp_tool_invocations ledger record "worker:justin", not the oauth
  // fallback — otherwise every key-authed call is mislabelled as an OAuth grant.
  (ctx as ExecutionContext & { props?: unknown }).props = {
    userId: "justin",
    scope: "remodel",
    kind: "worker",
  };
  return handler.fetch(request, env, ctx);
}

const oauthProvider = new OAuthProvider({
  apiHandlers: MCP_HANDLERS,
  defaultHandler: legacyHandler,
  authorizeEndpoint: "/oauth/authorize",
  tokenEndpoint: "/oauth/token",
  clientRegistrationEndpoint: "/oauth/register",
  scopesSupported: ["remodel"],
  // Single-operator connector: every lifetime is one year. The library
  // defaults (1h access / 30d refresh / 90d client registration) forced a
  // reconnect roughly hourly-to-quarterly and left 77 dead `client:` records
  // in OAUTH_KV. The 90d clientRegistrationTTL was the worst of them — it
  // deletes the client_id itself, so a stale claude.ai connector cannot even
  // refresh its way back and has to be removed and re-added by hand.
  accessTokenTTL: ONE_YEAR_SECONDS,
  refreshTokenTTL: ONE_YEAR_SECONDS,
  clientRegistrationTTL: ONE_YEAR_SECONDS,
});

const handler: ExportedHandler<Env> = {
  // withAbsoluteRegistrationUri patches the one RFC 7591 violation in the
  // provider's DCR response — a relative `registration_client_uri`, which is
  // what makes claude.ai report "Couldn't register with core-remodel's sign-in
  // service" even though the registration succeeded server-side.
  fetch: withAbsoluteRegistrationUri(async (request, env, ctx) => {
    // API-key callers skip the OAuth dance entirely; everyone else (including
    // every claude.ai connector) goes through the provider exactly as before.
    const direct = await handleApiKeyMcpRequest(request, env, ctx);
    return direct ?? oauthProvider.fetch(request, env, ctx);
  }),
  scheduled: (event, env, ctx) => legacyHandler.scheduled!(event, env, ctx),
  email: (message, env, ctx) => legacyHandler.email!(message, env, ctx),
};

export default handler;
